<?php
namespace Tests\Unit;use Tests\TestCase;use App\Features\Post\Enums\PostCategory;use App\Features\Post\Models\Post;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;
class PostDomainTest extends TestCase {use RefreshDatabase;public function test_category_descriptions_and_values():void{$this->assertSame('Teknologi & Koding',PostCategory::Teknologi->description());$this->assertSame('Pendidikan & Tutorial',PostCategory::Pendidikan->description());$this->assertSame('Gaya Hidup & Produktivitas',PostCategory::GayaHidup->description());$this->assertSame('Bisnis & Karir',PostCategory::Bisnis->description());$this->assertSame('Opini & Pemikiran',PostCategory::Opini->description());$this->assertSame('Umum',PostCategory::Umum->description());$this->assertCount(6,PostCategory::values());}public function test_slug_is_generated_and_unique():void{$u=User::factory()->create();$a=Post::factory()->for($u)->create(['title'=>'Belajar Laravel']);$b=Post::factory()->for($u)->create(['title'=>'Belajar Laravel']);$this->assertSame('belajar-laravel',$a->slug);$this->assertSame('belajar-laravel-2',$b->slug);}public function test_user_relations_and_admin_role():void{$u=User::factory()->create();$p=Post::factory()->for($u)->create();$this->assertTrue($u->posts->contains($p));$this->assertTrue($p->user->is($u));$this->assertFalse($u->isAdmin());$this->assertTrue(User::factory()->admin()->create()->isAdmin());}}
